\label{ex:ex3intro}
Consider the reaction network
\begin{equation}\label{eq:ex3intro}
{\cal N}_3=\{X_1+2X_2\to 2X_1+3X_2,\quad 2X_1+X_2\to X_1\}
\end{equation}

We may assume that $i_0=1$. By separating the first row in $\Gamma$ we write in block matrix form 
\begin{equation*}
\Gamma r(y)=\Gamma {\bar r}({\bar y})=
\begin{pmatrix}
0\\
\bar\Gamma
\end{pmatrix}{\bar r}({\bar y})
=\begin{pmatrix}
0\\ 
{\bar\Gamma}{\bar r}({\bar y})
\end{pmatrix},
\end{equation*}
so $\Gamma r(y)=0$ if and only if ${\bar\Gamma}{\bar r}({\bar y})=0$. 

For the nondegeneracy part we use (\ref{eq:degen}). We can write
$Dr(x)=D_{r(x)}R^tD_{1/x}$, where $R$ denotes the {\em reactant matrix} having the source complexes of $\cal N$ as columns, and $D_\eta$ denotes the diagonal matrix with entries of vector $\eta$ on the diagonal. If  $v=(v_1,\ldots, v_n)\in\text{im }\Gamma$ is a nonzero vector, then  $v_1=0$ and $\bar v=(v_2,\ldots, v_n)\in \text{im }{\bar\Gamma}$, $\bar v\neq 0$. Conversely, if ${\bar v}\in\text{im }{\bar\Gamma}$ is nonzero, then $v=(0,{\bar v})\in \text{im }{\Gamma}$ is nonzero. Using block matrix forms we have 
\begin{eqnarray*}
\Gamma Dr(x)|_{x=y}v=
\begin{pmatrix}
0\\
\bar\Gamma
\end{pmatrix}
D_{{\bar r}({\bar x}})
\begin{pmatrix}
R_1 &{\bar R}
\end{pmatrix}
\begin{pmatrix}
1/x_1 &0\\
0 &D_{1/{\bar x}}
\end{pmatrix}
\begin{pmatrix}
0\\
{\bar v}
\end{pmatrix}
=
\begin{pmatrix}
0\\
{\bar\Gamma}D_{{\bar r}({\bar x})}{\bar R}{\bar v}
\end{pmatrix}=
\begin{pmatrix}
0\\
{\bar\Gamma}D{{\bar r}({\bar x})}_{{\bar x}=
{\bar y}}{\bar v}
\end{pmatrix}
\end{eqnarray*}
so $\Gamma Dr(x)|_{x=y}v=0$ if and only if
${\bar\Gamma}D{{\bar r}({\bar x})}_{{\bar x}=
{\bar y}}{\bar v}=0$, 
therefore $y$ is nondegenerate if and only if ${\bar y}$ is.

{\em (Reaction network).}\label{def:rn}
A \em reaction network $\cal N$ on $n$ species is a finite set of {\em reactions}
$$a_k\to a'_k,\ k\in\{1,\ldots, r\}$$ 
where $a_k\in {\mathbb Z}_{\ge 0}^n$, $a'_k\in {\mathbb Z}^n$ and $a_k\neq a'_k$ for all $k\in\{1,\ldots, r\}$,

\label{ex:proj}
Let
$${\cal N}=\{2X_1+X_3\to X_1+X_2+3X_3,\;X_1+X_2\to 2X_2+2X_3,\;X_2+2X_3\to X_1\}.
$$

Dropping $X$ from notation the 2D projections of $\cal N$ on $\{1,2\}$ and $\{3\}$ are
\begin{eqnarray*}
{\cal N}_{\{1,2\}}&=&\{
(2,0)\to (1,1),\;
(1,1)\to (0,2),\;
(0,1) \to (1,0)\}\\
{\cal N}_{\{3\}}&=&\{
1\to 3,\;
0\to 2,\;
2 \to 0\}
\end{eqnarray*}

Figure \ref{fig:proj} illustrates arrow diagrams of some 2D and 1D projections of $\cal N$.

\label{prop:essential} Let $\cal N$ be a rank 1 reaction network and let ${\cal N}_I$ denote its essential projection. 
\begin{itemize} 
\item[(1)] if $\eta+tv$ is a (nondegenerate) positive equilibrium of $({\cal N},\kappa)$ then $\eta_I+t_0v_I$ is  a (nondegenerate) positive equilibrium  of $({\cal N}_I,\kappa)$.

\item[(2)] If $\eta'+t_0v_I$ is a (nondegenerate) positive steady state of $({\cal N}_I,\kappa)$ we choose for every $j\in J$ $\eta_j$ large enough so that $\eta_j+t_0v_j>0$ and we let $\eta=(\eta_I,\eta_J)\in {\mathbb Z}^S$. Then
$\eta+t_0v$ is a (nondegenerate) positive steady state of $({\cal N},\kappa)$.
\end{itemize}

1. We have

\begin{eqnarray*}
f(\eta,\kappa;t)&=&\prod_{j\in S\setminus I}(\eta_j+tv_j)^{\zeta_j}\left(
\sum_{k\in R\setminus R^0}\lambda_k\kappa_k(\eta_I+tv_I)^{(a_k)_I}
+\sum_{k\in R^0}(\lambda_k^+\kappa_k^+ +\lambda_k^-\kappa_k^-) (\eta_I+tv_I)^{{(a_k)}_I}\right)\\
&=& f(\eta_I,\kappa;t)
\end{eqnarray*}
and the conclusion follows from proposition \ref{prop:nonzerov} and lemma \ref{prop:DSSh}.

2. Similar to 1.

\label{defn:patterns}
\begin{itemize} 
\item[1.] We say that a reaction network $\cal N$ on one species {\em contains the $(\to, \gets)$ pattern} if it contains reactions $a\to a'$, $b\to b'$ with $a<a'$, $b'<b$ and $a<b$. ${\cal N}$ {\em has the $(\gets, \to)$ pattern} if it contains reactions $a\to a'$, $b\to b'$ with $a'<a$, $b'>b$ and $a<b$.

\item[2.] We say that a rank 1 reaction network $\cal N$ contains the $(\to, \gets)$ (or $(\gets,\to)$) pattern if there exists a 1D projection of $\cal N$ that has this pattern.
\end{itemize}

\label{def:2alt}
A rank 1 reaction network $\cal N$ that has a 1D projection containing both arrow patterns 
$$(\to,\gets,\to),\quad (\gets,\to,\gets)$$ on some 1D projection is called {\em 2-alternating}. We write ${\cal N}\in${\it 2-}$alt$\ .

\label{defn:zpattern}
Let ${\cal N}=\{a\to a', b\to b'\}$ be a rank 1 reaction network on two species. We say that ${\cal N}$ is a {\em zigzag} and if
\begin{itemize}
    \item[1.] $a\to a'$ and $b\to b'$ have opposite directions and
    \item[2.] $v_1v_2(b_1-a_1)(b_2-a_2)<0$.

The {\em slope} of zigzag ${\cal N}$ is defined as the slope of $b-a$, i.e. $\frac{b_2-a_2}{b_1-a_1}$. 
\end{itemize}

\label{ex:altz}
\text{ }

{\em 1.} The reaction network in Figure \ref{fig:egsd} contains the $(\to, \gets)$ pattern in both its 1D projection, and contains the $(\gets,\to)$ pattern in its projection on $\{1\}$ . This network is 2-alternating.

\smallskip
{\em 2.} The reaction network $\cal N$ in Example \ref{ex:proj}
contains the $(\to,\gets)$ pattern on all of its 1D projections, but it does not contain the $(\gets,\to)$ pattern. This network is not 1-alt complete.

\smallskip
{\em 3.} Let 
${\cal N}=\{(0,1,0)\to(1,2,-1),\ (1,0,1)\to(0,-1,2)\}$. This network contains the $(\to,\gets)$ pattern on its $\{1\}$ projection, and the $(\gets,\to)$ on its $\{2\}$ and $\{3\}$ projections. $\cal N$ is 1-alt complete. Moreover, $\cal N$ is a zigzag network.  ${\cal N}_{\{1,2\}}$ is a zigzag of slope -1 and ${\cal N}_{\{1,3\}}$ is a zigzag of slope 1.

{\em (Class ${\cal S}_2^{nz}$: two-source non-zigzag networks).}
A rank 1 reaction network $\cal N$ is said to be {\em a ${\cal S}_2^{nz}$ network} if it is essential, contains exactly two source complexes and ${\cal N}\in${\it 1-}$alt^c$\ $\setminus {\cal Z}$. 
We write ${\cal N}\in {\cal S}_2^{nz}.$

\label{prop:s2nz}
Let ${\cal N}$ be 1-alt complete. Then ${\cal N}\in{\cal S}_2^{nz}$ if and only if 

no subnetwork of $\cal N$ composed of three reactions is 1-alt complete.

\label{thm:mainext}
Let ${\cal N}$ be a rank 1 reaction network. 
Then 
\begin{itemize} 
\item[(1)] If $\cal N$ has capacity for MPE then either $\cal N$ is 1-alt complete or ${\cal N}\in{\cal S}_1$.
\item[(2)] If ${\cal N}\in{\cal S}_1$ or if the essential projection of ${\cal N}$ is in ${\cal D}={\cal S}_2^z\cup{\cal L}\cup {\cal S}_2^{nz}\cup {\cal C}$ then $\cal N$ has the capacity for MPE, but it does not have the capacity for MPNE. 
\item[(3)] If the essential projection of $\cal N$ is 1-alt complete and not in $\cal D$ then $\cal N$ has the capacity for MPNE.
\end{itemize}

